const body = $json.body ?? $json;
const clean = (value, max = 3000) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const start = new Date(clean(body.start, 80));
const end = new Date(clean(body.end, 80));
const duration = (end.getTime() - start.getTime()) / 60000;
const localStart = new Date(start.getTime() - 5 * 60 * 60 * 1000);
const weekday = localStart.getUTCDay();
const minutes = localStart.getUTCHours() * 60 + localStart.getUTCMinutes();
const booking = {
  lead_id: clean(body.lead_id, 120) || `booking-${Date.now()}`,
  full_name: clean(body.full_name, 160),
  email: clean(body.email, 200),
  phone: clean(body.phone, 80),
  company: clean(body.company, 200),
  service: clean(body.service, 240) || 'Reunión de diagnóstico',
  message: clean(body.message),
  start: start.toISOString(),
  end: end.toISOString(),
  timezone: 'America/Bogota',
  consent: body.consent === true ? 'SI' : 'NO',
  consent_at: clean(body.consent_at, 80) || new Date().toISOString()
};
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(booking.email);
const allowedTime = weekday >= 1 && weekday <= 5 && minutes >= 540 && minutes < 1020;
if (!booking.full_name || !validEmail || !booking.phone || booking.consent !== 'SI' || !Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime()) || duration !== 30 || start.getTime() <= Date.now() || !allowedTime) {
  throw new Error('Datos de reserva inválidos');
}
return [{ json: booking }];

const booking = $('Validar reserva').first().json;
const requestedStart = new Date(booking.start).getTime();
const requestedEnd = new Date(booking.end).getTime();
const events = $input.all().map(item => item.json).filter(event => event.id);
const conflicts = events.filter(event => {
  const eventStart = new Date(event.start?.dateTime ?? event.start?.date ?? event.start).getTime();
  const eventEnd = new Date(event.end?.dateTime ?? event.end?.date ?? event.end).getTime();
  return Number.isFinite(eventStart) && Number.isFinite(eventEnd) && requestedStart < eventEnd && requestedEnd > eventStart;
});
return [{ json: { ...booking, availability: conflicts.length === 0 ? 'available' : 'busy' } }];
